import json
import os
import time

from app.config import CACHE_PATH, CACHE_TTL


def _read_cache(path):
    try:
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def _write_cache(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp_path = path + '.tmp'
    with open(tmp_path, 'w', encoding='utf-8') as fh:
        json.dump(data, fh)
    os.replace(tmp_path, path)


def get_or_load(key, loader, now=None):
    """Return the cached value for ``key`` while fresh, else reload and persist.

    The cache is a shared JSON file at CACHE_PATH of the form
    ``{key: {stored_at: epoch_seconds, value: profile}}`` so values remain
    reusable by a new process. Entries younger than CACHE_TTL are served
    directly; anything older (or missing) is refreshed via ``loader``.
    """
    if now is None:
        now = time.time()
    key = str(key)
    data = _read_cache(CACHE_PATH)
    entry = data.get(key)
    if entry is not None:
        try:
            stored_at = float(entry['stored_at'])
        except (KeyError, TypeError, ValueError):
            stored_at = None
        if stored_at is not None and now - stored_at < CACHE_TTL:
            return entry['value']
    value = loader()
    data[key] = {'stored_at': now, 'value': value}
    _write_cache(CACHE_PATH, data)
    return value
"}

