from app.config import CACHE_TTL


def apply_response_policy(response):
    """Mark successful profile responses as public, long-TTL cacheable content."""
    if 200 <= response.status_code < 300:
        response.headers['Cache-Control'] = 'public, max-age={}'.format(CACHE_TTL)
    return response
